{"command":"mkdir -p src
cat << 'EOF' > src/json_parser.hpp
#ifndef JSON_PARSER_HPP
#define JSON_PARSER_HPP

#include <string>
#include <vector>
#include <map>
#include <memory>
#include <stdexcept>
#include <sstream>
#include <cctype>
#include <iomanip>
#include <iostream>

enum class JsonType { Null, Bool, Number, String, Array, Object };

struct JsonValue {
    JsonType type = JsonType::Null;
    bool bool_val = false;
    double num_val = 0.0;
    std::string num_str;
    std::string str_val;
    std::vector<JsonValue> arr_val;
    std::map<std::string, JsonValue> obj_val;

    // Node state for TUI
    int explicit_expanded = 0; // 0 = default, 1 = expanded, -1 = collapsed
    bool is_table_view = false;
    uint64_t id = 0;
};

class JsonParser {
    std::string src;
    size_t pos = 0;
    int line = 1;
    int col = 1;

    void advance() {
        if (pos < src.size()) {
            if (src[pos] == '\n') {
                line++;
                col = 1;
            } else {
                col++;
            }
            pos++;
        }
    }

    char peek() const {
        if (pos < src.size()) return src[pos];
        return '\0';
    }

    void skip_whitespace() {
        while (pos < src.size()) {
            char c = src[pos];
            if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
                advance();
            } else {
                break;
            }
        }
    }

    [[noreturn]] void error(const std::string& msg) {
        std::stringstream ss;
        std::string last_read = "";
        size_t start = (pos >= 10) ? pos - 10 : 0;
        last_read = src.substr(start, pos - start);
        ss << "\n[json.exception.parse_error.101] parse error at line " << line
           << ", column " << col << ": " << msg << "; last read: '" << last_read << "'\n";
        throw std::runtime_error(ss.str());
    }

public:
    JsonParser(const std::string& input) : src(input) {}

    JsonValue parse() {
        skip_whitespace();
        if (pos >= src.size()) {
            error("syntax error while parsing value - unexpected end of input");
        }
        JsonValue val = parse_value();
        skip_whitespace();
        return val;
    }

private:
    JsonValue parse_value() {
        skip_whitespace();
        char c = peek();
        if (c == 'n') return parse_null();
        if (c == 't' || c == 'f') return parse_bool();
        if (c == '"') return parse_string();
        if (c == '[') return parse_array();
        if (c == '{') return parse_object();
        if (c == '-' || (c >= '0' && c <= '9')) return parse_number();
        error("syntax error while parsing value - invalid literal");
    }

    JsonValue parse_null() {
        if (src.compare(pos, 4, "null") == 0) {
            for (int i = 0; i < 4; i++) advance();
            JsonValue v;
            v.type = JsonType::Null;
            return v;
        }
        error("syntax error while parsing null");
    }

    JsonValue parse_bool() {
        if (src.compare(pos, 4, "true") == 0) {
            for (int i = 0; i < 4; i++) advance();
            JsonValue v;
            v.type = JsonType::Bool;
            v.bool_val = true;
            return v;
        }
        if (src.compare(pos, 5, "false") == 0) {
            for (int i = 0; i < 5; i++) advance();
            JsonValue v;
            v.type = JsonType::Bool;
            v.bool_val = false;
            return v;
        }
        error("syntax error while parsing boolean");
    }

    JsonValue parse_string() {
        advance(); // skip opening quote
        std::string s;
        while (pos < src.size()) {
            char c = peek();
            if (c == '"') {
                advance(); // skip closing quote
                JsonValue v;
                v.type = JsonType::String;
                v.str_val = s;
                return v;
            }
            if (c == '\\') {
                advance();
                if (pos >= src.size()) error("unexpected end of input in string escape");
                char esc = peek();
                advance();
                if (esc == '"') s += '"';
                else if (esc == '\\') s += '\\';
                else if (esc == '/') s += '/';
                else if (esc == 'b') s += '\b';
                else if (esc == 'f') s += '\f';
                else if (esc == 'n') s += '\n';
                else if (esc == 'r') s += '\r';
                else if (esc == 't') s += '\t';
                else if (esc == 'u') {
                    // 4 hex digits
                    std::string hex;
                    for (int i = 0; i < 4; i++) {
                        if (pos >= src.size()) error("invalid unicode escape");
                        hex += peek();
                        advance();
                    }
                    uint32_t codepoint = std::stoul(hex, nullptr, 16);
                    if (codepoint <= 0x7F) {
                        s += static_cast<char>(codepoint);
                    } else if (codepoint <= 0x7FF) {
                        s += static_cast<char>(0xC0 | ((codepoint >> 6) & 0x1F));
                        s += static_cast<char>(0x80 | (codepoint & 0x3F));
                    } else {
                        s += static_cast<char>(0xE0 | ((codepoint >> 12) & 0x0F));
                        s += static_cast<char>(0x80 | ((codepoint >> 6) & 0x3F));
                        s += static_cast<char>(0x80 | (codepoint & 0x3F));
                    }
                } else {
                    s += esc;
                }
            } else {
                s += c;
                advance();
            }
        }
        error("unexpected end of input in string");
    }

    JsonValue parse_number() {
        size_t start = pos;
        if (peek() == '-') advance();
        while (pos < src.size() && (std::isdigit(peek()) || peek() == '.' || peek() == 'e' || peek() == 'E' || peek() == '+' || peek() == '-')) {
            advance();
        }
        std::string num_str = src.substr(start, pos - start);
        try {
            double val = std::stod(num_str);
            JsonValue v;
            v.type = JsonType::Number;
            v.num_val = val;
            v.num_str = num_str;
            return v;
        } catch (...) {
            error("invalid number format");
        }
    }

    JsonValue parse_array() {
        advance(); // skip '['
        JsonValue v;
        v.type = JsonType::Array;
        skip_whitespace();
        if (peek() == ']') {
            advance();
            return v;
        }
        while (true) {
            v.arr_val.push_back(parse_value());
            skip_whitespace();
            if (peek() == ']') {
                advance();
                break;
            }
            if (peek() == ',') {
                advance();
                skip_whitespace();
            } else {
                error("expected ',' or ']' in array");
            }
        }
        return v;
    }

    JsonValue parse_object() {
        advance(); // skip '{'
        JsonValue v;
        v.type = JsonType::Object;
        skip_whitespace();
        if (peek() == '}') {
            advance();
            return v;
        }
        while (true) {
            skip_whitespace();
            if (peek() != '"') {
                error("expected string key in object");
            }
            JsonValue key_val = parse_string();
            std::string key = key_val.str_val;
            skip_whitespace();
            if (peek() != ':') {
                error("expected ':' after key in object");
            }
            advance(); // skip ':'
            v.obj_val[key] = parse_value();
            skip_whitespace();
            if (peek() == '}') {
                advance();
                break;
            }
            if (peek() == ',') {
                advance();
                skip_whitespace();
            } else {
                error("expected ',' or '}' in object");
            }
        }
        return v;
    }
};

#endif
EOF
"}

