#ifndef TUI_HPP
#define TUI_HPP

#include "json_parser.hpp"
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <sstream>
#include <termios.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <signal.h>

struct InteractiveTarget {
    enum Type { NodeToggle, TableToggle } type;
    JsonValue* node = nullptr;
};

struct RenderLine {
    JsonValue* node = nullptr;
    int depth = 0;
    std::string indent_str;
    std::string key_prefix_ansi;
    std::string value_ansi;
    std::string comma_str;
    std::string line_full_ansi;
    bool custom_render = false;
    std::vector<InteractiveTarget> targets;
};

class TuiApp {
    JsonValue root;
    bool fullscreen = false;
    int depth_limit = 1;
    int selected_line = 0;
    int active_target = 0;
    int scroll_y = 0;
    int term_rows = 24;
    int term_cols = 80;
    int tty_fd = STDIN_FILENO;
    struct termios orig_termios;
    bool raw_mode_enabled = false;
    int last_rendered_lines_count = 0;

    static std::string repeat_utf8(const std::string& s, int n) {
        std::string res;
        if (n <= 0) return res;
        res.reserve(s.size() * n);
        for (int i = 0; i < n; i++) res += s;
        return res;
    }

    void update_term_size() {
        struct winsize ws;
        if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_row > 0) {
            term_rows = ws.ws_row;
            term_cols = ws.ws_col;
        } else {
            term_rows = 24;
            term_cols = 80;
        }
    }

    void enable_raw_mode() {
        if (!isatty(tty_fd)) return;
        tcgetattr(tty_fd, &orig_termios);
        struct termios raw = orig_termios;
        raw.c_lflag &= ~(ECHO | ICANON | ISIG | IEXTEN);
        raw.c_iflag &= ~(IXON | ICRNL | BRKINT | INPCK | ISTRIP);
        raw.c_oflag &= ~(OPOST);
        raw.c_cflag |= (CS8);
        raw.c_cc[VMIN] = 1;
        raw.c_cc[VTIME] = 0;
        tcsetattr(tty_fd, TCSAFLUSH, &raw);
        raw_mode_enabled = true;
    }

    void disable_raw_mode() {
        if (raw_mode_enabled) {
            tcsetattr(tty_fd, TCSAFLUSH, &orig_termios);
            raw_mode_enabled = false;
        }
    }

    static std::string escape_json_str(const std::string& s) {
        std::string out;
        for (char c : s) {
            if (c == '"') out += "\\\"";
            else if (c == '\\') out += "\\\\";
            else if (c == '\b') out += "\\b";
            else if (c == '\f') out += "\\f";
            else if (c == '\n') out += "\\n";
            else if (c == '\r') out += "\\r";
            else if (c == '\t') out += "\\t";
            else out += c;
        }
        return out;
    }

    static bool is_array_table_eligible(const JsonValue& node) {
        if (node.type != JsonType::Array || node.arr_val.empty()) return false;
        for (const auto& elem : node.arr_val) {
            if (elem.type != JsonType::Object) return false;
        }
        return true;
    }

    static std::string make_inverted(const std::string& ansi) {
        std::string s = ansi;
        if (s.rfind("\x1b[1m", 0) == 0) {
            s = s.substr(4);
        }
        return "\x1b[7m" + s + "\x1b[0m\x1b[39m\x1b[49m";
    }

    void generate_lines_recursive(JsonValue& node, int depth, bool is_last_child, const std::string& key_prefix, std::vector<RenderLine>& lines) {
        std::string indent(depth * 2, ' ');
        std::string key_ansi = key_prefix.empty() ? "" : "\x1b[94m\"" + escape_json_str(key_prefix) + "\"\x1b[39m: ";
        std::string comma = is_last_child ? "" : ",";

        if (node.type == JsonType::Null) {
            RenderLine line;
            line.node = &node;
            line.depth = depth;
            line.indent_str = indent;
            line.key_prefix_ansi = key_ansi;
            line.value_ansi = "\x1b[91mnull\x1b[39m";
            line.comma_str = comma;
            line.targets.push_back({InteractiveTarget::NodeToggle, &node});
            lines.push_back(line);
        } else if (node.type == JsonType::Bool) {
            RenderLine line;
            line.node = &node;
            line.depth = depth;
            line.indent_str = indent;
            line.key_prefix_ansi = key_ansi;
            std::string bstr = node.bool_val ? "true" : "false";
            line.value_ansi = "\x1b[93m" + bstr + "\x1b[39m";
            line.comma_str = comma;
            line.targets.push_back({InteractiveTarget::NodeToggle, &node});
            lines.push_back(line);
        } else if (node.type == JsonType::Number) {
            RenderLine line;
            line.node = &node;
            line.depth = depth;
            line.indent_str = indent;
            line.key_prefix_ansi = key_ansi;
            line.value_ansi = "\x1b[96m" + node.num_str + "\x1b[39m";
            line.comma_str = comma;
            line.targets.push_back({InteractiveTarget::NodeToggle, &node});
            lines.push_back(line);
        } else if (node.type == JsonType::String) {
            RenderLine line;
            line.node = &node;
            line.depth = depth;
            line.indent_str = indent;
            line.key_prefix_ansi = key_ansi;
            line.value_ansi = "\x1b[92m\"" + escape_json_str(node.str_val) + "\"\x1b[39m";
            line.comma_str = comma;
            line.targets.push_back({InteractiveTarget::NodeToggle, &node});
            lines.push_back(line);
        } else if (node.type == JsonType::Object) {
            bool is_expanded = (node.explicit_expanded == 1) || (node.explicit_expanded != -1 && depth <= depth_limit);
            std::string open_bracket = "\x1b[1m{\x1b[0m\x1b[39m\x1b[49m";
            if (node.obj_val.empty()) {
                RenderLine l1;
                l1.node = &node;
                l1.depth = depth;
                l1.indent_str = indent;
                l1.key_prefix_ansi = key_ansi;
                l1.value_ansi = open_bracket;
                l1.targets.push_back({InteractiveTarget::NodeToggle, &node});
                lines.push_back(l1);

                RenderLine l2;
                l2.node = &node;
                l2.depth = depth;
                l2.custom_render = true;
                l2.line_full_ansi = indent + "}" + comma;
                lines.push_back(l2);
            } else if (!is_expanded) {
                RenderLine line;
                line.node = &node;
                line.depth = depth;
                line.indent_str = indent;
                line.key_prefix_ansi = key_ansi;
                line.value_ansi = "\x1b[1m{...}" + comma + "\x1b[0m\x1b[39m\x1b[49m";
                line.comma_str = "";
                line.targets.push_back({InteractiveTarget::NodeToggle, &node});
                lines.push_back(line);
            } else {
                RenderLine header;
                header.node = &node;
                header.depth = depth;
                header.indent_str = indent;
                header.key_prefix_ansi = key_ansi;
                header.value_ansi = open_bracket;
                header.targets.push_back({InteractiveTarget::NodeToggle, &node});
                lines.push_back(header);

                size_t count = 0;
                size_t total = node.obj_val.size();
                for (auto& [k, child] : node.obj_val) {
                    count++;
                    generate_lines_recursive(child, depth + 1, count == total, k, lines);
                }

                RenderLine footer;
                footer.node = &node;
                footer.depth = depth;
                footer.custom_render = true;
                footer.line_full_ansi = indent + "}" + comma;
                lines.push_back(footer);
            }
        } else if (node.type == JsonType::Array) {
            bool eligible_table = is_array_table_eligible(node);
            if (node.is_table_view && eligible_table) {
                RenderLine header;
                header.node = &node;
                header.depth = depth;
                header.indent_str = indent;
                header.key_prefix_ansi = key_ansi;
                header.value_ansi = "\x1b[90m(array view)\x1b[39m";
                header.targets.push_back({InteractiveTarget::NodeToggle, &node});
                header.targets.push_back({InteractiveTarget::TableToggle, &node});
                lines.push_back(header);

                std::vector<std::string> keys;
                for (const auto& elem : node.arr_val) {
                    for (const auto& [k, v] : elem.obj_val) {
                        if (std::find(keys.begin(), keys.end(), k) == keys.end()) {
                            keys.push_back(k);
                        }
                    }
                }
                std::sort(keys.begin(), keys.end());

                int idx_w = std::to_string(node.arr_val.size() - 1).length();
                if (idx_w < 1) idx_w = 1;

                std::vector<int> col_widths(keys.size());
                for (size_t i = 0; i < keys.size(); i++) {
                    col_widths[i] = keys[i].length();
                }

                for (const auto& elem : node.arr_val) {
                    for (size_t i = 0; i < keys.size(); i++) {
                        auto it = elem.obj_val.find(keys[i]);
                        if (it != elem.obj_val.end()) {
                            int len = 0;
                            if (it->second.type == JsonType::String) len = it->second.str_val.length() + 2;
                            else if (it->second.type == JsonType::Number) len = it->second.num_str.length();
                            else if (it->second.type == JsonType::Bool) len = it->second.bool_val ? 4 : 5;
                            else if (it->second.type == JsonType::Null) len = 4;
                            else if (it->second.type == JsonType::Object) len = 5;
                            else if (it->second.type == JsonType::Array) len = 5;
                            if (len > col_widths[i]) col_widths[i] = len;
                        }
                    }
                }

                std::string idx_sp(idx_w, ' ');
                std::string top_b = "   ┏";
                std::string mid_b = "   ┡";
                std::string bot_b = "   └";
                std::string hdr_b = "  \x1b[90m" + idx_sp + "\x1b[39m┃";

                for (size_t i = 0; i < keys.size(); i++) {
                    top_b += repeat_utf8("━", col_widths[i]) + (i + 1 == keys.size() ? "┓" : "┳");
                    mid_b += repeat_utf8("━", col_widths[i]) + (i + 1 == keys.size() ? "┩" : "╇");
                    bot_b += repeat_utf8("─", col_widths[i]) + (i + 1 == keys.size() ? "┘" : "┴");

                    std::string k_pad = keys[i] + std::string(col_widths[i] - keys[i].length(), ' ');
                    hdr_b += k_pad + "┃";
                }

                RenderLine l_top; l_top.depth = depth; l_top.custom_render = true; l_top.line_full_ansi = top_b; lines.push_back(l_top);
                RenderLine l_hdr; l_hdr.depth = depth; l_hdr.custom_render = true; l_hdr.line_full_ansi = hdr_b; lines.push_back(l_hdr);
                RenderLine l_mid; l_mid.depth = depth; l_mid.custom_render = true; l_mid.line_full_ansi = mid_b; lines.push_back(l_mid);

                for (size_t r = 0; r < node.arr_val.size(); r++) {
                    std::string idx_str = std::to_string(r);
                    std::string idx_fmt = idx_str + std::string(idx_w - idx_str.length(), ' ');
                    std::string row_ansi = "  \x1b[90m" + idx_fmt + "\x1b[39m│";

                    const auto& elem = node.arr_val[r];
                    for (size_t i = 0; i < keys.size(); i++) {
                        auto it = elem.obj_val.find(keys[i]);
                        std::string cell_ansi;
                        int cell_len = 0;
                        if (it != elem.obj_val.end()) {
                            const auto& cv = it->second;
                            if (cv.type == JsonType::Null) {
                                cell_len = 4;
                                std::string pad(col_widths[i] - cell_len, ' ');
                                cell_ansi = "\x1b[91mnull" + pad + "\x1b[39m";
                            } else if (cv.type == JsonType::Bool) {
                                std::string bs = cv.bool_val ? "true" : "false";
                                cell_len = bs.length();
                                std::string pad(col_widths[i] - cell_len, ' ');
                                cell_ansi = "\x1b[93m" + bs + pad + "\x1b[39m";
                            } else if (cv.type == JsonType::Number) {
                                cell_len = cv.num_str.length();
                                std::string pad(col_widths[i] - cell_len, ' ');
                                cell_ansi = "\x1b[96m" + cv.num_str + pad + "\x1b[39m";
                            } else if (cv.type == JsonType::String) {
                                std::string sv = "\"" + escape_json_str(cv.str_val) + "\"";
                                cell_len = sv.length();
                                std::string pad(col_widths[i] - cell_len, ' ');
                                cell_ansi = "\x1b[92m" + sv + pad + "\x1b[39m";
                            } else if (cv.type == JsonType::Object) {
                                cell_len = 5;
                                std::string pad(col_widths[i] - cell_len, ' ');
                                cell_ansi = "\x1b[1m{...}" + pad + "\x1b[0m";
                            } else if (cv.type == JsonType::Array) {
                                cell_len = 5;
                                std::string pad(col_widths[i] - cell_len, ' ');
                                cell_ansi = "\x1b[1m[...]" + pad + "\x1b[0m";
                            }
                        } else {
                            cell_ansi = std::string(col_widths[i], ' ');
                        }
                        row_ansi += cell_ansi + "│";
                    }
                    RenderLine l_row; l_row.node = const_cast<JsonValue*>(&elem); l_row.depth = depth;
                    l_row.custom_render = true; l_row.line_full_ansi = row_ansi;
                    lines.push_back(l_row);
                }

                RenderLine l_bot; l_bot.depth = depth; l_bot.custom_render = true; l_bot.line_full_ansi = bot_b; lines.push_back(l_bot);
            } else {
                bool is_expanded = (node.explicit_expanded == 1) || (node.explicit_expanded != -1 && (depth == 0 || depth <= depth_limit - 1));
                std::string open_bracket = "\x1b[1m[\x1b[0m\x1b[39m\x1b[49m";
                if (node.arr_val.empty()) {
                    RenderLine line;
                    line.node = &node;
                    line.depth = depth;
                    line.indent_str = indent;
                    line.key_prefix_ansi = key_ansi;
                    line.value_ansi = "\x1b[1m[...]" + comma + "\x1b[0m\x1b[39m\x1b[49m";
                    line.targets.push_back({InteractiveTarget::NodeToggle, &node});
                    lines.push_back(line);
                } else if (!is_expanded) {
                    RenderLine line;
                    line.node = &node;
                    line.depth = depth;
                    line.indent_str = indent;
                    line.key_prefix_ansi = key_ansi;
                    std::string tbl_btn = eligible_table ? "   \x1b[90m(table view)\x1b[39m" : "";
                    line.value_ansi = "\x1b[1m[...]" + comma + "\x1b[0m\x1b[39m\x1b[49m" + tbl_btn;
                    line.targets.push_back({InteractiveTarget::NodeToggle, &node});
                    if (eligible_table) line.targets.push_back({InteractiveTarget::TableToggle, &node});
                    lines.push_back(line);
                } else {
                    RenderLine header;
                    header.node = &node;
                    header.depth = depth;
                    header.indent_str = indent;
                    header.key_prefix_ansi = key_ansi;
                    std::string tbl_btn = eligible_table ? "   \x1b[90m(table view)\x1b[39m" : "";
                    header.value_ansi = open_bracket + tbl_btn;
                    header.targets.push_back({InteractiveTarget::NodeToggle, &node});
                    if (eligible_table) header.targets.push_back({InteractiveTarget::TableToggle, &node});
                    lines.push_back(header);

                    for (size_t i = 0; i < node.arr_val.size(); i++) {
                        generate_lines_recursive(node.arr_val[i], depth + 1, i + 1 == node.arr_val.size(), "", lines);
                    }

                    RenderLine footer;
                    footer.node = &node;
                    footer.depth = depth;
                    footer.custom_render = true;
                    footer.line_full_ansi = indent + "]" + comma;
                    lines.push_back(footer);
                }
            }
        }
    }

public:
    TuiApp(JsonValue r, bool fs = false) : root(r), fullscreen(fs) {
        if (!isatty(STDIN_FILENO)) {
            tty_fd = open("/dev/tty", O_RDWR);
            if (tty_fd < 0) tty_fd = STDIN_FILENO;
        }
    }

    ~TuiApp() {
        if (tty_fd >= 0 && tty_fd != STDIN_FILENO) close(tty_fd);
    }

    std::vector<RenderLine> generate_lines() {
        std::vector<RenderLine> lines;
        generate_lines_recursive(root, 0, true, "", lines);
        return lines;
    }

    void run() {
        enable_raw_mode();
        update_term_size();

        std::string init_str = "\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?25l";
        if (fullscreen) {
            init_str += "\x1b[?1049h\x1b[2J\x1b[H";
        }
        if (write(STDOUT_FILENO, init_str.c_str(), init_str.size()) < 0) {}

        bool running = true;
        while (running) {
            update_term_size();
            auto lines = generate_lines();

            if (selected_line >= (int)lines.size()) selected_line = (int)lines.size() - 1;
            if (selected_line < 0) selected_line = 0;

            if (selected_line < scroll_y) scroll_y = selected_line;
            if (selected_line >= scroll_y + term_rows) scroll_y = selected_line - term_rows + 1;

            std::string frame;
            if (fullscreen) {
                frame += "\x1b[H";
            } else {
                if (last_rendered_lines_count > 0) {
                    frame += "\r\x1b[" + std::to_string(last_rendered_lines_count) + "A";
                }
            }

            int view_count = 0;
            int end_y = std::min((int)lines.size(), scroll_y + term_rows);

            for (int i = scroll_y; i < end_y; i++) {
                std::string line_str;
                if (lines[i].custom_render) {
                    line_str = lines[i].line_full_ansi;
                    if (i == selected_line) {
                        line_str = make_inverted(line_str);
                    }
                } else {
                    std::string val_part = lines[i].value_ansi;
                    if (i == selected_line) {
                        if (active_target == 1 && lines[i].targets.size() > 1) {
                            size_t pos = val_part.find("(table view)");
                            std::string target_lbl = "(table view)";
                            if (pos == std::string::npos) {
                                pos = val_part.find("(array view)");
                                target_lbl = "(array view)";
                            }
                            if (pos != std::string::npos) {
                                val_part.replace(pos, target_lbl.length(), "\x1b[7m\x1b[90m" + target_lbl + "\x1b[0m\x1b[39m\x1b[49m");
                            }
                        } else {
                            val_part = make_inverted(val_part);
                        }
                    }
                    line_str = lines[i].indent_str + lines[i].key_prefix_ansi + val_part + lines[i].comma_str;
                }

                if (fullscreen) {
                    int r_idx = i - scroll_y + 1;
                    frame += "\x1b[" + std::to_string(r_idx) + ";1H\x1b[2K" + line_str;
                } else {
                    frame += "\r\x1b[2K" + line_str + "\r\n";
                }
                view_count++;
            }

            if (fullscreen && view_count < term_rows) {
                for (int r = view_count + 1; r <= term_rows; r++) {
                    frame += "\x1b[" + std::to_string(r) + ";1H\x1b[2K";
                }
            }

            last_rendered_lines_count = view_count;
            if (write(STDOUT_FILENO, frame.c_str(), frame.size()) < 0) {}

            char buf[32];
            int n = read(tty_fd, buf, sizeof(buf));
            if (n <= 0) break;

            for (int b_idx = 0; b_idx < n; b_idx++) {
                char c = buf[b_idx];
                if (c == 'q' || c == 27) {
                    if (b_idx + 2 < n && buf[b_idx + 1] == '[') {
                        char seq = buf[b_idx + 2];
                        if (seq == 'A') { selected_line--; active_target = 0; }
                        else if (seq == 'B') { selected_line++; active_target = 0; }
                        else if (seq == 'C') {
                            if (selected_line < (int)lines.size() && lines[selected_line].targets.size() > 1) {
                                if (active_target < (int)lines[selected_line].targets.size() - 1) active_target++;
                            }
                        } else if (seq == 'D') {
                            if (active_target > 0) active_target--;
                        } else if (seq == '5' && b_idx + 3 < n && buf[b_idx + 3] == '~') {
                            selected_line -= term_rows - 2; b_idx += 2;
                        } else if (seq == '6' && b_idx + 3 < n && buf[b_idx + 3] == '~') {
                            selected_line += term_rows - 2; b_idx += 2;
                        }
                        b_idx += 2;
                    } else {
                        running = false;
                    }
                } else if (c == 'j') {
                    selected_line++; active_target = 0;
                } else if (c == 'k') {
                    selected_line--; active_target = 0;
                } else if (c == 'h') {
                    if (active_target > 0) active_target--;
                } else if (c == 'l') {
                    if (selected_line < (int)lines.size() && lines[selected_line].targets.size() > 1) {
                        if (active_target < (int)lines[selected_line].targets.size() - 1) active_target++;
                    }
                } else if (c == '\r' || c == '\n' || c == ' ') {
                    if (selected_line < (int)lines.size() && !lines[selected_line].targets.empty()) {
                        int tgt_idx = std::min(active_target, (int)lines[selected_line].targets.size() - 1);
                        auto& tgt = lines[selected_line].targets[tgt_idx];
                        if (tgt.type == InteractiveTarget::TableToggle) {
                            tgt.node->is_table_view = !tgt.node->is_table_view;
                        } else if (tgt.type == InteractiveTarget::NodeToggle) {
                            if (tgt.node->explicit_expanded == 1) tgt.node->explicit_expanded = -1;
                            else if (tgt.node->explicit_expanded == -1) tgt.node->explicit_expanded = 1;
                            else {
                                bool is_exp = (tgt.node->type == JsonType::Object) ? (lines[selected_line].depth <= depth_limit) : (lines[selected_line].depth == 0 || lines[selected_line].depth <= depth_limit - 1);
                                tgt.node->explicit_expanded = is_exp ? -1 : 1;
                            }
                        }
                    }
                } else if (c == '+') {
                    if (selected_line < (int)lines.size() && lines[selected_line].node && lines[selected_line].node->type != JsonType::String && lines[selected_line].node->type != JsonType::Number && lines[selected_line].node->type != JsonType::Bool && lines[selected_line].node->type != JsonType::Null) {
                        lines[selected_line].node->explicit_expanded = 1;
                    } else {
                        depth_limit++;
                    }
                } else if (c == '-') {
                    if (depth_limit > 0) depth_limit--;
                } else if (c == 'G') {
