                        if (!lines[l_idx].targets.empty() || (!lines[l_idx].custom_render && !lines[l_idx].value_ansi.empty())) {
                            selected_line = l_idx;
                            break;
                        }
                    }
                    active_target = 0;
                } else if (c == 'g') {
                    if (b_idx + 1 < n && buf[b_idx + 1] == 'g') {
                        selected_line = 0;
                        active_target = 0;
                        b_idx++;
                    }
                }
            }
        }

        std::string cleanup_str = "\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l\x1b[?25h";
        if (fullscreen) {
            cleanup_str += "\x1b[?1049l";
        }
        if (write(STDOUT_FILENO, cleanup_str.c_str(), cleanup_str.size()) < 0) {}
        disable_raw_mode();
    }
};

#endif
