                                std::string bs = cv.bool_val ? "true" : "false";
                                cell_len = bs.length();
                                std::string pad(col_widths[i] - cell_len, ' ');
                                cell_ansi = "\x1b[93m" + bs + pad + "\x1b[39m";
                            } else if (cv.type == JsonType::Number) {
                                cell_len = cv.num_str.length();
                                std::string pad(col_widths[i] - cell_len, ' ');
