                    RenderLine line;
                    line.node = &node;
                    line.depth = depth;
                    line.indent_str = indent;
                    line.key_prefix_ansi = key_ansi;
                    line.value_ansi = "\x1b[1m[...]" + comma + "\x1b[0m\x1b[39m\x1b[49m";
